if git show HEAD:"apps/web/content/docs/dev/auth/le-modele-et-le-contrat.mdx" 2>/dev/null | grep -qF "## Le jeton de réinitialisation"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "identification des personnes sur chaque média" "packages/contracts/src/legal/processingRegister.ts" 2>/dev/null || { echo "❌ lancer d'abord apply-fix-registre-tags.sh"; exit 1; }
